function validate([root1, root2, target]) {
  const inspect = (list, name) => {
    if (!Array.isArray(list) || list.length === 0 || list[0] === null) return `${name} needs at least 1 node.`;
    // Rebuild the tree from level order: each node takes the next two entries as its children.
    const nodes = [{ val: list[0], low: -Infinity, high: Infinity }];
    let next = 1;
    for (let head = 0; head < nodes.length; head++) {
      const { val, low, high } = nodes[head];
      if (!Number.isInteger(val) || val < -1e9 || val > 1e9) return `Every value in ${name} is an integer from -10^9 to 10^9.`;
      if (val <= low || val >= high) return `${name} must be a binary search tree: smaller values to the left, larger to the right.`;
      if (next < list.length && list[next] !== null) nodes.push({ val: list[next], low, high: val });
      next++;
      if (next < list.length && list[next] !== null) nodes.push({ val: list[next], low: val, high });
      next++;
    }
    if (next < list.length) return `${name} has entries after its last possible child.`;
    if (nodes.length > 5000) return `${name} has at most 5000 nodes.`;
    return null;
  };
  const problem = inspect(root1, 'root1') ?? inspect(root2, 'root2');
  if (problem) return problem;
  if (!Number.isInteger(target) || target < -1e9 || target > 1e9) return 'target is an integer from -10^9 to 10^9.';
  return null;
}

