function twoSumBSTs(root1, root2, target) {
  const ascending = [];
  const descending = [];
  let small = root1;
  let large = root2;
  while (true) {
    while (small !== null) {
      ascending.push(small);
      small = small.left;
    }
    while (large !== null) {
      descending.push(large);
      large = large.right;
    }
    if (ascending.length === 0 || descending.length === 0) {
      return false;
    }
    const low = ascending[ascending.length - 1];
    const high = descending[descending.length - 1];
    const sum = low.val + high.val;
    if (sum === target) {
      return true;
    }
    if (sum < target) {
      ascending.pop();
      small = low.right;
    } else {
      descending.pop();
      large = high.left;
    }
  }
}

