function twoSumBSTs(root1, root2, target) {
  // Gather both trees' values with a plain stack walk, then test every pair.
  const valuesOf = root => {
    const values = [];
    const stack = [root];
    while (stack.length) {
      const node = stack.pop();
      if (!node) continue;
      values.push(node.val);
      stack.push(node.left, node.right);
    }
    return values;
  };
  const first = valuesOf(root1);
  const second = valuesOf(root2);
  for (const a of first) for (const b of second) if (a + b === target) return true;
  return false;
}

