function generate(rand, size) {
  const large = size === 'large';
  const span = large ? 1e9 : 12;
  const pick = () => Math.floor(rand() * (2 * span + 1)) - span;
  const makeTree = () => {
    const count = large ? 700 + Math.floor(rand() * 250) : 1 + Math.floor(rand() * 7);
    const seen = new Set();
    while (seen.size < count) seen.add(pick());
    const values = [...seen];
    // Insert in random order (bushy), sorted order (a chain) or reverse order (a chain the other way).
    const shape = rand();
    if (shape < 0.15) values.sort((a, b) => a - b);
    else if (shape < 0.3) values.sort((a, b) => b - a);
    const nodes = [];
    for (const val of values) {
      nodes.push({ val, left: null, right: null });
      const index = nodes.length - 1;
      if (index === 0) continue;
      let at = 0;
      for (;;) {
        const side = val < nodes[at].val ? 'left' : 'right';
        if (nodes[at][side] === null) { nodes[at][side] = index; break; }
        at = nodes[at][side];
      }
    }
    // Level-order list with null for missing children, trailing nulls removed.
    const out = [];
    const queue = [0];
    for (let q = 0; q < queue.length; q++) {
      if (queue[q] === null) { out.push(null); continue; }
      out.push(nodes[queue[q]].val);
      queue.push(nodes[queue[q]].left, nodes[queue[q]].right);
    }
    while (out[out.length - 1] === null) out.pop();
    return [out, values];
  };
  const [root1, values1] = makeTree();
  const [root2, values2] = makeTree();
  // Half the time the target is a real pair's sum; otherwise it is random (and usually missed on large trees).
  let target = rand() < 0.5 ? values1[Math.floor(rand() * values1.length)] + values2[Math.floor(rand() * values2.length)] : 2 * pick();
  target = Math.max(-1e9, Math.min(1e9, target));
  return [root1, root2, target];
}
